def finalString(s: str) -> str:
    # Use a list for efficient append and reversal
    result = []
    for c in s:
        if c == 'i':
            # Reverse the string typed so far
            result.reverse()
        else:
            # Append current character
            result.append(c)
    # Join the list into a string for the final result
    return ''.join(result)
